"""Pricing helpers."""

VAT_RATE = 0.23


def gross(net):
    return net * (1 + VAT_RATE)


def tax(net):
    return net * VAT_RATE


def label(net):
    return f"{net} plus {net * VAT_RATE:.2f}"


def version():
    return "0.23.0"
